    /** 采购申请表id */
    id: number;

    constructor(data?: IUpdatePurchaseApplyOrderParam) {
        if (data) {
            for (var property in data) {
                if (data.hasOwnProperty(property))
                    (<any>this)[property] = (<any>data)[property];
            }
        }
    }

    init(_data?: any) {
        if (_data) {
            this.type = _data["type"];
            this.department_id = _data["department_id"];
            this.applicant_id = _data["applicant_id"];
            if (Array.isArray(_data["tags"])) {
                this.tags = [] as any;
                for (let item of _data["tags"])
                    this.tags.push(item);
            }
            this.remark = _data["remark"];
            if (Array.isArray(_data["details"])) {
                this.details = [] as any;
                for (let item of _data["details"])
                    this.details.push(PurchaseApplyOrderDetailResult.fromJS(item));
            }
            this.is_pass = _data["is_pass"];
            this.id = _data["id"];
        }
    }

    static fromJS(data: any): UpdatePurchaseApplyOrderParam {
        data = typeof data === 'object' ? data : {};
        let result = new UpdatePurchaseApplyOrderParam();
        result.init(data);
        return result;
    }

    toJSON(data?: any) {
        data = typeof data === 'object' ? data : {};
        data["type"] = this.type;
        data["department_id"] = this.department_id;
        data["applicant_id"] = this.applicant_id;
        if (Array.isArray(this.tags)) {
            data["tags"] = [];
            for (let item of this.tags)
                data["tags"].push(item);
        }
        data["remark"] = this.remark;
        if (Array.isArray(this.details)) {
            data["details"] = [];
            for (let item of this.details)
                data["details"].push(item.toJSON());
        }
        data["is_pass"] = this.is_pass;
        data["id"] = this.id;
        return data;
    }

